public static Object[] generateValidInput(Random random) {
    int type = random.nextInt(5);
    int[][] testArray;

    switch (type) {
        case 0: // Empty array
            testArray = new int[0][];
            break;
        case 1: // Single tuple
            testArray = new int[][]{{random.nextInt(21) - 10, random.nextInt(21) - 10}};
            break;
        case 2: // Duplicate tuples (unsorted and sorted)
            int val1 = random.nextInt(21) - 10;
            int val2 = random.nextInt(21) - 10;
            testArray = new int[][]{{val1, val2}, {Math.min(val1, val2), Math.max(val1, val2)}, {val2, val1}};
            break;
        case 3: // Boundary values
            testArray = new int[][]{
                {Integer.MIN_VALUE, Integer.MAX_VALUE},
                {Integer.MAX_VALUE, Integer.MIN_VALUE},
                {0, 0},
                {1, -1},
                {-1, 1}
            };
            break;
        default: // Random size with random values
            int size = random.nextInt(10) + 1;
            testArray = new int[size][2];
            for (int i = 0; i < size; i++) {
                testArray[i][0] = random.nextInt(100) - 50;
                testArray[i][1] = random.nextInt(100) - 50;
            }
            break;
    }

    return new Object[]{testArray};
}

