class AddNestedTuples {

    public static int[][] addNestedTuples(int[][] testTup1, int[][] testTup2) {
        int rows = testTup1.length;
        int cols = testTup1[0].length;
        int[][] result = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
