public static Object[] generateValidInput(Random random) {
    int choice = random.nextInt(6);
    int[][] testTup1;
    int[][] testTup2;

    switch (choice) {
        case 0: // Normal case with small random values
            int rows1 = 1 + random.nextInt(5);
            int cols1 = 1 + random.nextInt(3);
            testTup1 = new int[rows1][cols1];
            testTup2 = new int[rows1][cols1];
            for (int i = 0; i < rows1; i++) {
                for (int j = 0; j < cols1; j++) {
                    testTup1[i][j] = random.nextInt(21) - 10;
                    testTup2[i][j] = random.nextInt(21) - 10;
                }
            }
            break;
        case 1: // Single element tuple
            testTup1 = new int[][]{{random.nextInt(21) - 10}};
            testTup2 = new int[][]{{random.nextInt(21) - 10}};
            break;
        case 2: // Boundary values with max/min int
            int rows2 = 1 + random.nextInt(3);
            int cols2 = 1 + random.nextInt(2);
            testTup1 = new int[rows2][cols2];
            testTup2 = new int[rows2][cols2];
            for (int i = 0; i < rows2; i++) {
                for (int j = 0; j < cols2; j++) {
                    int val1 = random.nextBoolean() ? Integer.MAX_VALUE : Integer.MIN_VALUE;
                    int val2 = random.nextBoolean() ? Integer.MAX_VALUE : Integer.MIN_VALUE;
                    testTup1[i][j] = val1;
                    testTup2[i][j] = val2;
                }
            }
            break;
        case 3: // Larger size with random values including zeros
            int rows3 = 2 + random.nextInt(4);
            int cols3 = 2 + random.nextInt(3);
            testTup1 = new int[rows3][cols3];
            testTup2 = new int[rows3][cols3];
            for (int i = 0; i < rows3; i++) {
                for (int j = 0; j < cols3; j++) {
                    testTup1[i][j] = random.nextInt(2001) - 1000;
                    testTup2[i][j] = random.nextInt(2001) - 1000;
                }
            }
            break;
        case 4: // All zeros tuples
            int rows4 = 1 + random.nextInt(3);
            int cols4 = 1 + random.nextInt(2);
            testTup1 = new int[rows4][cols4];
            testTup2 = new int[rows4][cols4];
            break;
        default: // Mixed positive/negative and boundary cases
            int rows5 = 2 + random.nextInt(3);
            int cols5 = 2 + random.nextInt(2);
            testTup1 = new int[rows5][cols5];
            testTup2 = new int[rows5][cols5];
            for (int i = 0; i < rows5; i++) {
                for (int j = 0; j < cols5; j++) {
                    if (random.nextBoolean()) {
                        testTup1[i][j] = random.nextInt(21) - 10;
                    } else {
                        testTup1[i][j] = random.nextBoolean() ? Integer.MAX_VALUE : Integer.MIN_VALUE;
                    }
                    if (random.nextBoolean()) {
                        testTup2[i][j] = random.nextInt(21) - 10;
                    } else {
                        testTup2[i][j] = random.nextBoolean() ? Integer.MAX_VALUE : Integer.MIN_VALUE;
                    }
                }
            }
            break;
    }

    return new Object[]{testTup1, testTup2};
}

