public static Object[] generateValidInput(Random random) {
    // Possible strings for patterns and colors
    String[] patternChoices = {"a", "b", "c", "d", "e"};
    String[] colorChoices = {"red", "green", "blue", "yellow", "orange"};

    String[] patterns;
    String[] colors;

    int choice = random.nextInt(10);
    switch (choice) {
        case 0: // both null
            patterns = null;
            colors = null;
            break;
        case 1: // patterns null, colors non-null
            patterns = null;
            colors = new String[]{colorChoices[random.nextInt(colorChoices.length)]};
            break;
        case 2: // colors null, patterns non-null
            patterns = new String[]{patternChoices[random.nextInt(patternChoices.length)]};
            colors = null;
            break;
        case 3: // both empty arrays
            patterns = new String[0];
            colors = new String[0];
            break;
        case 4: // arrays of different lengths (patterns longer -> exception)
            {
                int lenP = 2 + random.nextInt(3); // 2..4
                int lenC = 1 + random.nextInt(2); // 1..2 (ensuring lenP > lenC)
                patterns = new String[lenP];
                colors = new String[lenC];
                for (int i = 0; i < lenP; i++) {
                    patterns[i] = patternChoices[random.nextInt(patternChoices.length)];
                }
                for (int i = 0; i < lenC; i++) {
                    colors[i] = colorChoices[random.nextInt(colorChoices.length)];
                }
            }
            break;
        case 5: // arrays of different lengths (colors longer -> no exception, extra colors ignored)
            {
                int lenP = 1 + random.nextInt(2); // 1..2
                int lenC = 2 + random.nextInt(3); // 2..4 (ensuring lenC > lenP)
                patterns = new String[lenP];
                colors = new String[lenC];
                for (int i = 0; i < lenP; i++) {
                    patterns[i] = patternChoices[random.nextInt(patternChoices.length)];
                }
                for (int i = 0; i < lenC; i++) {
                    colors[i] = colorChoices[random.nextInt(colorChoices.length)];
                }
            }
            break;
        case 6: // valid bijection (with possible repetition)
            {
                int k = 1 + random.nextInt(3); // number of distinct patterns (1..3)
                // choose k distinct patterns
                Set<String> patSet = new HashSet<>();
                while (patSet.size() < k) {
                    patSet.add(patternChoices[random.nextInt(patternChoices.length)]);
                }
                List<String> patList = new ArrayList<>(patSet);
                // choose k distinct colors
                Set<String> colSet = new HashSet<>();
                while (colSet.size() < k) {
                    colSet.add(colorChoices[random.nextInt(colorChoices.length)]);
                }
                List<String> colList = new ArrayList<>(colSet);
                // build mapping
                Map<String, String> mapping = new HashMap<>();
                for (int i = 0; i < k; i++) {
                    mapping.put(patList.get(i), colList.get(i));
                }
                // generate arrays of length L (k to k+4)
                int L = k + random.nextInt(5);
                patterns = new String[L];
                colors = new String[L];
                for (int i = 0; i < L; i++) {
                    String pat = patList.get(random.nextInt(k));
                    patterns[i] = pat;
                    colors[i] = mapping.get(pat);
                }
            }
            break;
        case 7: // invalid: pattern duplicate with different color
            {
                int L = 2 + random.nextInt(3); // 2..4
                patterns = new String[L];
                colors = new String[L];
                // pick a pattern that appears twice with different colors
                String pat = patternChoices[random.nextInt(patternChoices.length)];
                String col1 = colorChoices[random.nextInt(colorChoices.length)];
                String col2;
                do {
                    col2 = colorChoices[random.nextInt(colorChoices.length)];
                } while (col2.equals(col1));
                patterns[0] = pat;
                colors[0] = col1;
                patterns[1] = pat;
                colors[1] = col2;
                // fill rest randomly
                for (int i = 2; i < L; i++) {
                    patterns[i] = patternChoices[random.nextInt(patternChoices.length)];
                    colors[i] = colorChoices[random.nextInt(colorChoices.length)];
                }
            }
            break;
        case 8: // invalid: two different patterns map to same color
            {
                int L = 2 + random.nextInt(3); // 2..4
                patterns = new String[L];
                colors = new String[L];
                // pick two distinct patterns
                String pat1 = patternChoices[random.nextInt(patternChoices.length)];
                String pat2;
                do {
                    pat2 = patternChoices[random.nextInt(patternChoices.length)];
                } while (pat2.equals(pat1));
                // same color for both
                String col = colorChoices[random.nextInt(colorChoices.length)];
                patterns[0] = pat1;
                colors[0] = col;
                patterns[1] = pat2;
                colors[1] = col;
                // fill rest randomly
                for (int i = 2; i < L; i++) {
                    patterns[i] = patternChoices[random.nextInt(patternChoices.length)];
                    colors[i] = colorChoices[random.nextInt(colorChoices.length)];
                }
            }
            break;
        default: // random valid or invalid (covers remaining diversity)
            {
                int L = 0; // L can be 0
                if (random.nextBoolean()) {
                    L = 1 + random.nextInt(5); // 1..5
                } // else L stays 0
                patterns = new String[L];
                colors = new String[L];
                for (int i = 0; i < L; i++) {
                    patterns[i] = patternChoices[random.nextInt(patternChoices.length)];
                    colors[i] = colorChoices[random.nextInt(colorChoices.length)];
                }
                // With some probability, make the input valid by ensuring bijection
                // but here we just generate random, which may be valid or invalid.
            }
            break;
    }

    return new Object[]{colors, patterns};
}

