    // Randomly choose between normal, boundary, and edge cases
    int caseType = random.nextInt(5);

    String x, y;
    int m, n;

    switch (caseType) {
        case 0: // Empty strings
            x = "";
            y = "";
            m = 0;
            n = 0;
            break;
        case 1: // One empty string
            x = "";
            y = randomString(random, random.nextInt(5) + 1);
            m = 0;
            n = y.length();
            break;
        case 2: // All same characters
            char c = (char)('a' + random.nextInt(26));
            int len1 = random.nextInt(10) + 1;
            int len2 = random.nextInt(10) + 1;
            x = String.valueOf(c).repeat(len1);
            y = String.valueOf(c).repeat(len2);
            m = len1;
            n = len2;
            break;
        case 3: // Boundary lengths (1)
            x = String.valueOf((char)('a' + random.nextInt(26)));
            y = String.valueOf((char)('a' + random.nextInt(26)));
            m = 1;
            n = 1;
            break;
        default: // Normal random case
            m = random.nextInt(10) + 1;
            n = random.nextInt(10) + 1;
            x = randomString(random, m);
            y = randomString(random, n);
            break;
    }

    return new Object[]{x, y, m, n};
}

// Helper method to generate random string of given length
private static String randomString(Random random, int length) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < length; i++) {
        sb.append((char)('a' + random.nextInt(26)));
    }
    return sb.toString();
}

