public static Object[] generateValidInput(Random random) {
    String[] testCases = {
        "",
        " ",
        "a",
        "a b c,d e f",
        "Python language, Programming language.",
        "ram reshma,ram rahim",
        "., ,.",
        ",,,",
        "   ",
        "a.b,c d.e,f g",
        ".,a,.",
        "hello world, test. input",
        "single,comma",
        "trailing,",
        ",leading",
        "multiple   spaces",
        "tab\there",
        "newline\nhere",
        "spec!al@chars#",
        "only,commas",
        "only.dots",
        "only spaces"
    };

    // Randomly select one of the predefined test cases for consistent coverage
    String text = testCases[random.nextInt(testCases.length)];

    // Occasionally generate random strings with mixed characters
    if (random.nextBoolean()) {
        int len = random.nextInt(20);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < len; i++) {
            int choice = random.nextInt(4);
            if (choice == 0) {
                sb.append(' ');
            } else if (choice == 1) {
                sb.append(',');
            } else if (choice == 2) {
                sb.append('.');
            } else {
                sb.append((char)('a' + random.nextInt(26)));
            }
        }
        text = sb.toString();
    }

    return new Object[]{text};
}

