import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class BigSum {

    public static int bigSum(int[] nums) {
        int max = Integer.MIN_VALUE;
        int min = Integer.MAX_VALUE;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] > max) {
                max = nums[i];
            }
            if (nums[i] < min) {
                min = nums[i];
            }
        }
        return max + min;
    }
}

