    int choice = random.nextInt(10);
    int[] nums;
    switch (choice) {
        case 0:
            nums = new int[0];
            break;
        case 1:
            nums = null;
            break;
        case 2:
            nums = new int[1];
            if (random.nextBoolean()) {
                nums[0] = random.nextInt();
            } else {
                nums[0] = random.nextBoolean() ? Integer.MIN_VALUE : Integer.MAX_VALUE;
            }
            break;
        case 3:
            int len = random.nextInt(20) + 1;
            int val = random.nextInt();
            nums = new int[len];
            for (int i = 0; i < len; i++) {
                nums[i] = val;
            }
            break;
        case 4:
            nums = new int[]{Integer.MIN_VALUE, Integer.MAX_VALUE, 0, -1, 1, random.nextInt()};
            break;
        case 5:
            int size = random.nextInt(10) + 2;
            nums = new int[size];
            nums[0] = Integer.MIN_VALUE;
            nums[1] = Integer.MAX_VALUE;
            for (int i = 2; i < size; i++) {
                nums[i] = random.nextInt();
            }
            break;
        default:
            int n = random.nextInt(100) + 1;
            nums = new int[n];
            for (int i = 0; i < n; i++) {
                nums[i] = random.nextInt();
            }
            if (n > 2 && random.nextBoolean()) {
                nums[random.nextInt(n)] = Integer.MAX_VALUE;
                nums[random.nextInt(n)] = Integer.MIN_VALUE;
                nums[random.nextInt(n)] = 0;
                nums[random.nextInt(n)] = -1;
                nums[random.nextInt(n)] = 1;
            }
            break;
    }
    return new Object[]{nums};
}

