public static Object[] generateValidInput(Random random) {
    int size1 = random.nextInt(6);
    int size2 = random.nextInt(6);

    java.util.List<Integer> nums1 = new java.util.ArrayList<>();
    java.util.List<Integer> nums2 = new java.util.ArrayList<>();

    for (int k = 0; k < 2; k++) {
        java.util.List<Integer> list = (k == 0) ? nums1 : nums2;
        int size = (k == 0) ? size1 : size2;

        for (int i = 0; i < size; i++) {
            int choice = random.nextInt(5);
            int value;

            if (choice == 0) {
                value = random.nextInt();
            } else if (choice == 1) {
                value = random.nextBoolean() ? Integer.MAX_VALUE : Integer.MIN_VALUE;
            } else if (choice == 2) {
                value = 0;
            } else if (choice == 3) {
                value = random.nextBoolean() ? 1 : -1;
            } else {
                value = random.nextInt(201) - 100;
            }

            list.add(value);
        }
    }

    int total = size1 * size2;
    int mode = random.nextInt(5);
    int n;

    if (mode == 0) {
        n = 0;
    } else if (mode == 1) {
        n = total;
    } else if (mode == 2) {
        n = Math.min(1, total);
    } else if (mode == 3) {
        n = total == 0 ? 0 : 1 + random.nextInt(total);
    } else {
        n = random.nextInt(total + 1);
    }

    return new Object[]{nums1, nums2, n};
}

