public static Object[] generateValidInput(Random random) {
    String[] adverbs = {"clearly", "seriously", "unfortunately", "quickly", "slowly", "happily", "sadly", "angrily", "easily", "hardly", "barely", "rarely", "simply", "truly", "fully", "totally", "completely", "absolutely", "definitely", "certainly"};
    String[] prefixes = {"", " ", "hello ", "The ", "A ", "123 ", "!! ", "?? ", "... ", "some prefix "};
    String[] suffixes = {"", " ", "!", "!!", "?", "??", ".", "...", " world", " there", " are many roses", " we can see the sky"};

    // Generate a random adverb and surround it with random prefix/suffix
    String adverb = adverbs[random.nextInt(adverbs.length)];
    String text = prefixes[random.nextInt(prefixes.length)] + adverb + suffixes[random.nextInt(suffixes.length)];

    // Occasionally generate edge cases
    int choice = random.nextInt(10);
    if (choice == 0) {
        text = ""; // empty string
    } else if (choice == 1) {
        text = "no adverbs here"; // no adverb
    } else if (choice == 2) {
        text = "ly"; // just "ly" at start
    } else if (choice == 3) {
        text = "onlyly"; // adverb at very start
    } else if (choice == 4) {
        text = "abcly"; // adverb at very end
    } else if (choice == 5) {
        text = "lyly"; // contains "ly" but not adverb pattern
    } else if (choice == 6) {
        text = "a".repeat(1000) + adverb; // very long text
    } else if (choice == 7) {
        text = adverb + " " + adverb; // multiple adverbs, should find first
    } else if (choice == 8) {
        text = "wordly"; // word ending with "ly" but not adverb? still matches pattern
    }

    return new Object[]{text};
}

