        // 10% chance: null
        tuples = null;
    } else if (choice < 20) {
        // 10% chance: empty array
        tuples = new int[0][];
    } else if (choice < 30) {
        // 10% chance: single tuple with edge values
        tuples = new int[1][2];
        // Randomly choose to include extreme values
        if (random.nextBoolean()) {
            tuples[0][0] = (random.nextBoolean() ? Integer.MIN_VALUE : Integer.MAX_VALUE);
            tuples[0][1] = (random.nextBoolean() ? Integer.MIN_VALUE : Integer.MAX_VALUE);
        } else {
            tuples[0][0] = random.nextInt(2001) - 1000; // -1000 to 1000
            tuples[0][1] = random.nextInt(2001) - 1000;
        }
    } else {
        // 70% chance: random array of size 1-10
        int size = random.nextInt(10) + 1; // 1 to 10
        tuples = new int[size][2];
        for (int i = 0; i < size; i++) {
            // Occasionally include extreme values
            if (random.nextInt(10) == 0) {
                tuples[i][0] = (random.nextBoolean() ? Integer.MIN_VALUE : Integer.MAX_VALUE);
                tuples[i][1] = (random.nextBoolean() ? Integer.MIN_VALUE : Integer.MAX_VALUE);
            } else {
                tuples[i][0] = random.nextInt(2001) - 1000; // -1000 to 1000
                tuples[i][1] = random.nextInt(2001) - 1000;
            }
            // Occasionally make a pair with same value (diff=0)
            if (random.nextInt(5) == 0) {
                tuples[i][0] = tuples[i][1];
            }
        }
    }
    return new Object[]{tuples};
}

