    int[] specialValues = {0, 1, 2, 3, 4, 5, 10, -1, Integer.MAX_VALUE, Integer.MIN_VALUE};
    int n;
    if (random.nextBoolean()) {
        n = specialValues[random.nextInt(specialValues.length)];
    } else {
        n = random.nextInt(12); // small values to avoid overflow
    }
    return new Object[]{n};
}

