public static Object[] generateValidInput(Random random) {
    String[] keyPool = {"a", "b", "c", "d", "e", "f", "g", "h"};
    HashMap<String, Integer> d1 = new HashMap<>();
    HashMap<String, Integer> d2 = new HashMap<>();

    int size1 = random.nextInt(keyPool.length + 1); // 0..8 (includes empty map)
    for (int i = 0; i < size1; i++) {
        String key = keyPool[random.nextInt(keyPool.length)];
        d1.put(key, randomValue(random));
    }

    int size2 = random.nextInt(keyPool.length + 1);
    for (int i = 0; i < size2; i++) {
        String key = keyPool[random.nextInt(keyPool.length)];
        d2.put(key, randomValue(random));
    }

    // Occasionally force common keys to guarantee the addition branch
    if (random.nextBoolean() && !d1.isEmpty()) {
        for (String key : d1.keySet()) {
            if (random.nextBoolean()) {
                d2.put(key, randomValue(random));
            }
        }
    }

    // Occasionally force disjoint keys to cover the non-overlap branches
    if (random.nextInt(4) == 0) {
        d1.clear();
        d2.clear();
        d1.put("x", randomValue(random));
        d2.put("y", randomValue(random));
    }

    return new Object[]{d1, d2};
}

private static Integer randomValue(Random random) {
    switch (random.nextInt(6)) {
        case 0: return 0;
        case 1: return 1;
        case 2: return -1;
        case 3: return Integer.MAX_VALUE;
        case 4: return Integer.MIN_VALUE;
        default: return random.nextInt(2001) - 1000;
    }
}

