public static Object[] generateValidInput(Random random) {
    int choice = random.nextInt(5);
    int[] arrayNums;

    switch (choice) {
        case 0:
            // Empty array
            arrayNums = new int[0];
            break;
        case 1:
            // Single element (could be positive, negative, or zero)
            arrayNums = new int[1];
            int singleValue = random.nextInt(3) - 1; // -1, 0, or 1
            arrayNums[0] = singleValue;
            break;
        case 2:
            // Boundary values with mixed positive, negative, and zero
            int[] boundaryValues = {Integer.MIN_VALUE, Integer.MAX_VALUE, 0, 1, -1};
            int boundarySize = random.nextInt(boundaryValues.length + 1);
            arrayNums = new int[boundarySize];
            for (int i = 0; i < boundarySize; i++) {
                arrayNums[i] = boundaryValues[random.nextInt(boundaryValues.length)];
            }
            break;
        case 3:
            // Random array with mixed positive, negative, and zero values
            int length = random.nextInt(10); // 0 to 9 elements
            arrayNums = new int[length];
            for (int i = 0; i < length; i++) {
                // Generate random values including 0, positive, and negative
                int value;
                int type = random.nextInt(3);
                if (type == 0) {
                    value = 0;
                } else if (type == 1) {
                    value = random.nextInt(100) + 1; // 1 to 100
                } else {
                    value = -(random.nextInt(100) + 1); // -1 to -100
                }
                arrayNums[i] = value;
            }
            break;
        case 4:
            // All positive, all negative, or all zero arrays
            int allType = random.nextInt(3);
            int size = random.nextInt(8) + 1; // 1 to 8 elements
            arrayNums = new int[size];
            for (int i = 0; i < size; i++) {
                if (allType == 0) {
                    arrayNums[i] = random.nextInt(50) + 1; // all positive
                } else if (allType == 1) {
                    arrayNums[i] = -(random.nextInt(50) + 1); // all negative
                } else {
                    arrayNums[i] = 0; // all zeros
                }
            }
            break;
        default:
            arrayNums = new int[0];
            break;
    }

    return new Object[]{arrayNums};
}

