    for (int i = 0; i < n; i++) {
        triangle[i] = new int[i + 1];
        for (int j = 0; j <= i; j++) {
            // Use random values that include boundary and normal cases
            int choice = random.nextInt(10);
            if (choice == 0) {
                triangle[i][j] = 0;
            } else if (choice == 1) {
                triangle[i][j] = 1;
            } else if (choice == 2) {
                triangle[i][j] = -1;
            } else if (choice == 3) {
                triangle[i][j] = Integer.MAX_VALUE;
            } else if (choice == 4) {
                triangle[i][j] = Integer.MIN_VALUE;
            } else {
                triangle[i][j] = random.nextInt(200) - 100; // -100 to 99
            }
        }
    }

    // Occasionally produce edge cases
    if (random.nextBoolean()) {
        // Sometimes make a single-element triangle
        if (random.nextInt(5) == 0) {
            triangle = new int[][]{{random.nextInt(20) - 10}};
        }
    }

    return new Object[]{triangle};
}

