public static Object[] generateValidInput(Random random) {
    // Randomly choose one of several test scenarios
    int scenario = random.nextInt(8);

    switch (scenario) {
        case 0: // Normal case with some common elements
            return new Object[]{
                new int[]{1, 1, 3, 4, 5, 6, 7},
                new int[]{0, 1, 2, 3, 4, 5, 7},
                new int[]{0, 1, 2, 3, 4, 5, 7}
            };
        case 1: // Normal case with different common elements
            return new Object[]{
                new int[]{1, 1, 3, 4, 5, 6, 7},
                new int[]{0, 1, 2, 3, 4, 6, 5},
                new int[]{0, 1, 2, 3, 4, 6, 7}
            };
        case 2: // All arrays identical
            return new Object[]{
                new int[]{5, 5, 5, 5},
                new int[]{5, 5, 5, 5},
                new int[]{5, 5, 5, 5}
            };
        case 3: // No common elements
            return new Object[]{
                new int[]{1, 2, 3},
                new int[]{4, 5, 6},
                new int[]{7, 8, 9}
            };
        case 4: // Single element arrays
            return new Object[]{
                new int[]{42},
                new int[]{42},
                new int[]{42}
            };
        case 5: // Empty arrays
            return new Object[]{
                new int[]{},
                new int[]{},
                new int[]{}
            };
        case 6: // Boundary values
            return new Object[]{
                new int[]{Integer.MIN_VALUE, 0, Integer.MAX_VALUE},
                new int[]{Integer.MIN_VALUE, 0, Integer.MAX_VALUE},
                new int[]{Integer.MIN_VALUE, 0, Integer.MAX_VALUE}
            };
        default: // Random generated arrays
            int length = random.nextInt(10) + 1; // 1 to 10
            int[] a1 = new int[length];
            int[] a2 = new int[length];
            int[] a3 = new int[length];
            for (int i = 0; i < length; i++) {
                int val = random.nextInt(20) - 10; // -10 to 9
                a1[i] = val;
                // Sometimes make all three the same
                if (random.nextBoolean()) {
                    a2[i] = val;
                    a3[i] = val;
                } else {
                    a2[i] = random.nextInt(20) - 10;
                    a3[i] = random.nextInt(20) - 10;
                }
            }
            return new Object[]{a1, a2, a3};
    }
}

