    int m;
    int n;
    int shape = random.nextInt(6);
    switch (shape) {
        case 0:
            m = 0;
            n = 0;
            break;
        case 1:
            m = 0;
            n = random.nextInt(4) + 1;
            break;
        case 2:
            m = random.nextInt(4) + 1;
            n = 0;
            break;
        case 3:
            m = 1;
            n = 1;
            break;
        case 4:
            m = 2;
            n = 2;
            break;
        default:
            m = random.nextInt(5);
            n = random.nextInt(5);
            break;
    }

    int rows = m + 1;
    int cols = n + 1;
    int[][] cost = new int[rows][cols];

    int fillMode = random.nextInt(6);
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            switch (fillMode) {
                case 0:
                    cost[i][j] = random.nextInt(21) - 10;
                    break;
                case 1:
                    cost[i][j] = 1;
                    break;
                case 2:
                    cost[i][j] = 0;
                    break;
                case 3:
                    cost[i][j] = random.nextBoolean() ? Integer.MAX_VALUE : Integer.MIN_VALUE;
                    break;
                case 4:
                    cost[i][j] = -1;
                    break;
                default:
                    int r = random.nextInt(10);
                    if (r == 0) {
                        cost[i][j] = Integer.MAX_VALUE;
                    } else if (r == 1) {
                        cost[i][j] = Integer.MIN_VALUE;
                    } else if (r == 2) {
                        cost[i][j] = 0;
                    } else if (r == 3) {
                        cost[i][j] = 1;
                    } else {
                        cost[i][j] = random.nextInt(21) - 10;
                    }
                    break;
            }
        }
    }

    return new Object[]{cost, m, n};
}

