    int r;
    int h;
    int choice = random.nextInt(5);
    switch (choice) {
        case 0:
            // Normal positive values
            r = 1 + random.nextInt(100);
            h = 1 + random.nextInt(100);
            break;
        case 1:
            // Boundary: zero values
            r = 0;
            h = 0;
            break;
        case 2:
            // Boundary: one value is zero, other positive
            if (random.nextBoolean()) {
                r = 0;
                h = 1 + random.nextInt(100);
            } else {
                r = 1 + random.nextInt(100);
                h = 0;
            }
            break;
        case 3:
            // Negative values (edge case)
            r = -1 - random.nextInt(100);
            h = -1 - random.nextInt(100);
            break;
        case 4:
            // Extreme values
            if (random.nextBoolean()) {
                r = Integer.MAX_VALUE;
                h = Integer.MAX_VALUE;
            } else {
                r = Integer.MIN_VALUE;
                h = Integer.MIN_VALUE;
            }
            break;
        default:
            // Fallback: random integers (could be negative or positive)
            r = random.nextInt();
            h = random.nextInt();
            break;
    }
    return new Object[]{r, h};
}

