import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class SortMatrix {

    public static int[][] sortMatrix(int[][] m) {
        int rows = m.length;

        Integer[] indices = new Integer[rows];
        for (int i = 0; i < rows; i++) {
            indices[i] = i;
        }

        Arrays.sort(indices, (i1, i2) -> {
            int sum1 = Arrays.stream(m[i1]).sum();
            int sum2 = Arrays.stream(m[i2]).sum();
            if (sum1 != sum2) {
                return sum1 - sum2;
            }
            return Integer.compare(m[i1][0], m[i2][0]); // For tie-breaking
        });

        int[][] sortedMatrix = new int[rows][m[0].length];
        for (int i = 0; i < rows; i++) {
            sortedMatrix[i] = m[indices[i]];
        }

        return sortedMatrix;
    }
}

