    int n;
    String s;

    int caseType = random.nextInt(6);
    switch (caseType) {
        case 0:
            // Empty string
            s = "";
            n = random.nextInt(10) + 1;
            break;
        case 1:
            // Single character
            s = random.nextBoolean() ? "0" : "1";
            n = random.nextInt(10) + 1;
            break;
        case 2:
            // All zeros
            int len1 = random.nextInt(20) + 1;
            s = "0".repeat(len1);
            n = random.nextInt(10) + 1;
            break;
        case 3:
            // All ones
            int len2 = random.nextInt(20) + 1;
            s = "1".repeat(len2);
            n = random.nextInt(10) + 1;
            break;
        case 4:
            // Random binary string with length up to 20
            int len3 = random.nextInt(20) + 1;
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < len3; i++) {
                sb.append(random.nextBoolean() ? '1' : '0');
            }
            s = sb.toString();
