      @ ensures n == 0 ==> \result == 0;
      @ ensures \result == n || (n - \result > 0 && (\exists int i; 0 <= i && i + (n - \result) <= n; (long)arr[i + (n - \result) - 1] - (long)arr[i] <= (long)k));
      @*/
    public static int removals(int[] arr, int n, int k) {
        Arrays.sort(arr);  // Sorting to effectively find the appropriate range
        int left = 0;
        int right = 0;
        int maxRemovals = n;  // Maximum elements to be removed.

        /*@ maintaining 0 <= left && left <= right && right <= n;
          @ maintaining 0 <= maxRemovals && maxRemovals <= n;
          @ decreasing n - left;
