public static Object[] generateValidInput(Random random) {
    HashMap<String, Integer> dict = new HashMap<>();
    int size = random.nextInt(5); // 0-4 entries (covers empty map case)
    int baseValue = random.nextInt(21) - 10; // base value in [-10, 10]

    boolean allSame = random.nextBoolean();
    for (int i = 0; i < size; i++) {
        String key = "key" + i;
        if (allSame) {
            dict.put(key, baseValue);
        } else {
            // vary values so not all are equal
            dict.put(key, baseValue + (i % 2 == 0 ? 0 : 1));
        }
    }

    int n;
    switch (random.nextInt(5)) {
        case 0:
            n = baseValue; // matches when allSame
            break;
        case 1:
            n = baseValue + 1; // mismatch
            break;
        case 2:
            n = 0; // boundary value
            break;
        case 3:
            n = Integer.MAX_VALUE; // extreme boundary
            break;
        default:
            n = Integer.MIN_VALUE; // extreme boundary
            break;
    }

    return new Object[]{dict, Integer.valueOf(n)};
}

