import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class CheckSubset {

    public static Boolean checkSubset(int[] testTup1, int[] testTup2) {
        Set<Integer> set = new HashSet<>();
        for (int i = 0; i < testTup1.length; i++) {
            set.add(testTup1[i]);
        }
        for (int i = 0; i < testTup2.length; i++) {
            if (!set.contains(testTup2[i])) {
                return false;
            }
        }
        return true;
    }
}

