public static Object[] generateValidInput(Random random) {
    HashMap<Integer, String> dict = new HashMap<Integer, String>();
    int scenario = random.nextInt(5);
    switch (scenario) {
        case 0:
            // Empty map
            break;
        case 1:
            // Single entry with boundary key
            int[] boundaryKeys = {0, 1, -1, Integer.MAX_VALUE, Integer.MIN_VALUE};
            dict.put(boundaryKeys[random.nextInt(boundaryKeys.length)], "value");
            break;
        case 2:
            // Small map with typical values
            int n = 2 + random.nextInt(4);
            for (int i = 0; i < n; i++) {
                dict.put(random.nextInt(100), "str" + i);
            }
            break;
        case 3:
            // Map including negative and boundary keys
            dict.put(0, "zero");
            dict.put(-1, "neg");
            dict.put(Integer.MAX_VALUE, "max");
            dict.put(Integer.MIN_VALUE, "min");
            break;
        default:
            // Larger map with mixed positive/negative keys
            int size = 5 + random.nextInt(15);
            for (int i = 0; i < size; i++) {
                dict.put(random.nextInt(2001) - 1000, "val" + random.nextInt(100));
            }
            break;
    }
    return new Object[]{dict};
}

